import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';
import { AgGridReact } from 'ag-grid-react'; 
import React, { useRef } from "react";
import { useQueryState } from "nuqs";  // Import nuqs
import data from "./sample-app.json";

function App() {
  const gridRef = useRef(null);

  // Manage URL state
  const [hiddenColumns, setHiddenColumns] = useQueryState("hidden", { defaultValue: [] });
  const [sortModel, setSortModel] = useQueryState("sort", { defaultValue: [] });
  const [filterModel, setFilterModel] = useQueryState("filter", { defaultValue: {} });
  const [searchText, setSearchText] = useQueryState("search", { defaultValue: "" });
  const [pageSize, setPageSize] = useQueryState("pageSize", { defaultValue: 20 });
  const [currentPage, setCurrentPage] = useQueryState("page", { defaultValue: 0 });

  // Column definitions with dynamic visibility
  const colDefs = Object.keys(data[0]).map((key) => ({
    field: key,
    hide: hiddenColumns.includes(key),
    filter: true,
    floatingFilter: true,
    sortable: true
  }));

  // Update state when grid is ready
  const onGridReady = (params) => {
    gridRef.current = params.api;
    params.api.setSortModel(sortModel);
    params.api.setFilterModel(filterModel);
    params.api.paginationSetPageSize(pageSize);
    params.api.paginationGoToPage(currentPage);
    params.api.setQuickFilter(searchText);
  };

  // Event Handlers
  const toggleColumn = (col) => setHiddenColumns(hiddenColumns.includes(col) ? hiddenColumns.filter(c => c !== col) : [...hiddenColumns, col]);
  const onSortChanged = () => setSortModel(gridRef.current.getSortModel());
  const onFilterChanged = () => setFilterModel(gridRef.current.getFilterModel());
  const onPageSizeChange = (e) => {
    setPageSize(Number(e.target.value));
    gridRef.current.paginationSetPageSize(Number(e.target.value));
  };
  const onPaginationChange = () => setCurrentPage(gridRef.current.paginationGetCurrentPage());

  return (
    <div className="ag-theme-alpine" style={{ height: 600, width: "80%", margin: "auto" }}>
      {/* Controls */}
      <div>
        <input type="text" placeholder="Search..." value={searchText} onChange={(e) => {
          setSearchText(e.target.value);
          gridRef.current.setQuickFilter(e.target.value);
        }} />
        <select onChange={onPageSizeChange} value={pageSize}>
          <option value={10}>10</option>
          <option value={20}>20</option>
          <option value={50}>50</option>
        </select>
        <button onClick={() => gridRef.current.exportDataAsCsv()}>Export CSV</button>
      </div>

      {/* Column Toggle */}
      <div>
        {Object.keys(data[0]).map((col) => (
          <button key={col} onClick={() => toggleColumn(col)}>
            {hiddenColumns.includes(col) ? `Show ${col}` : `Hide ${col}`}
          </button>
        ))}
      </div>

      {/* AG Grid */}
      <AgGridReact
        ref={gridRef}
        rowData={data}
        columnDefs={colDefs}
        pagination={true}
        paginationPageSize={pageSize}
        onGridReady={onGridReady}
        onSortChanged={onSortChanged}
        onFilterChanged={onFilterChanged}
        onPaginationChanged={onPaginationChange}
      />

      {/* Pagination Controls */}
      <div>
        <button onClick={() => gridRef.current.paginationGoToPreviousPage()}>Previous</button>
        <button onClick={() => gridRef.current.paginationGoToNextPage()}>Next</button>
      </div>
    </div>
  );
}

export default App;
